import React, { useState, useEffect } from 'react';
import './App.css';

// Import components
import Navbar from './components/ui/Navbar';
import Sidebar from './components/ui/Sidebar';
import MarketSummary from './components/dashboard/MarketSummary';
import Watchlist from './components/dashboard/Watchlist';
import StatsCards from './components/dashboard/StatsCards';
import PriceChart from './components/trading/PriceChart';
import TradePanel from './components/trading/TradePanel';
import HoldingsTable from './components/portfolio/HoldingsTable';
import SectorAllocation from './components/portfolio/SectorAllocation';
import PerformanceMetrics from './components/portfolio/PerformanceMetrics';

const API_URL = 'http://localhost:5000/api';

function App() {
  // Auth state
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  // Trading state
  const [symbol, setSymbol] = useState('RELIANCE');
  const [price, setPrice] = useState(null);
  const [balance, setBalance] = useState(0);
  const [portfolio, setPortfolio] = useState([]);
  const [activeTab, setActiveTab] = useState('dashboard');

  // Fetch portfolio when logged in
  useEffect(() => {
    if (isLoggedIn) {
      fetchPortfolio();
      const interval = setInterval(() => {
        fetchPortfolio();
        if (activeTab === 'trading') {
          fetchPrice();
        }
      }, 30000);
      return () => clearInterval(interval);
    }
  }, [isLoggedIn, activeTab]);

  // Auth functions
  const register = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, email, password })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const login = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      if (data.message) {
        setIsLoggedIn(true);
        setMessage(`Welcome ${username}!`);
        fetchPortfolio();
      } else {
        setMessage(data.error || 'Login failed');
      }
    } catch (error) {
      setMessage('Error connecting to server. Is Flask running?');
    }
    setLoading(false);
  };

  const logout = async () => {
    await fetch(`${API_URL}/logout`, {
      method: 'POST',
      credentials: 'include'
    });
    setIsLoggedIn(false);
    setMessage('Logged out');
  };

  // Trading functions
  const fetchPrice = async () => {
    try {
      const response = await fetch(`${API_URL}/price/${symbol}`);
      const data = await response.json();
      if (data.price) {
        setPrice(data.price);
      }
    } catch (error) {
      console.error('Error fetching price:', error);
    }
  };

  const fetchPortfolio = async () => {
    try {
      const response = await fetch(`${API_URL}/portfolio`, {
        credentials: 'include'
      });
      const data = await response.json();
      if (data.portfolio !== undefined) {
        setPortfolio(data.portfolio || []);
        setBalance(data.balance || 0);
      }
    } catch (error) {
      console.error('Error fetching portfolio:', error);
    }
  };

  const handleBuy = async (quantity) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/buy`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      setMessage('Error buying stock');
    }
    setLoading(false);
  };

  const handleSell = async (quantity) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/sell`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ symbol, quantity })
      });
      const data = await response.json();
      setMessage(data.message || data.error);
      if (data.balance !== undefined) {
        setBalance(data.balance);
        fetchPortfolio();
      }
    } catch (error) {
      setMessage('Error selling stock');
    }
    setLoading(false);
  };

  // Render login/register
  if (!isLoggedIn) {
    return (
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '100vh',
        background: '#0a0e17',
        color: 'white',
        fontFamily: 'Arial'
      }}>
        <div style={{
          background: '#141b2b',
          padding: '40px',
          borderRadius: '12px',
          width: '100%',
          maxWidth: '400px',
          border: '1px solid #2a3a5c'
        }}>
          <h1 style={{ textAlign: 'center', color: '#4CAF50' }}>📈 DemoTrader</h1>
          <p style={{ textAlign: 'center', color: '#4CAF50' }}>🎉 Get ₹1,00,000 FREE!</p>
          
          {message && <div style={{
            padding: '10px',
            margin: '10px 0',
            borderRadius: '6px',
            background: '#1a2332',
            textAlign: 'center'
          }}>{message}</div>}
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Login</h2>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={login}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Login'}
          </button>
          
          <h2 style={{ color: '#8a9bb5', fontSize: '18px', marginTop: '20px' }}>Register</h2>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{
              width: '100%',
              padding: '12px',
              margin: '8px 0',
              background: '#1a2332',
              border: '1px solid #2a3a5c',
              borderRadius: '6px',
              color: 'white'
            }}
          />
          <button
            onClick={register}
            disabled={loading}
            style={{
              width: '100%',
              padding: '12px',
              marginTop: '10px',
              background: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              fontSize: '16px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            {loading ? '...' : 'Register & Get ₹1L'}
          </button>
        </div>
      </div>
    );
  }

  // Render dashboard
  const renderContent = () => {
    switch(activeTab) {
      case 'dashboard':
        return (
          <>
            <MarketSummary />
            <Watchlist onSelectStock={(s) => { setSymbol(s); setActiveTab('trading'); }} />
            <StatsCards portfolio={portfolio} />
            {portfolio.length > 0 && (
              <PerformanceMetrics holdings={portfolio} balance={balance} />
            )}
            {portfolio.length > 0 && (
              <HoldingsTable holdings={portfolio} />
            )}
            {portfolio.length > 0 && (
              <SectorAllocation holdings={portfolio} />
            )}
          </>
        );

      case 'trading':
        return (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
              <div>
                <PriceChart symbol={symbol} />
              </div>
              <div>
                <TradePanel
                  symbol={symbol}
                  price={price}
                  onBuy={handleBuy}
                  onSell={handleSell}
                  loading={loading}
                />
              </div>
            </div>
            <div style={{ marginTop: '20px' }}>
              <HoldingsTable holdings={portfolio} />
            </div>
          </>
        );

      case 'portfolio':
        return (
          <>
            <PerformanceMetrics holdings={portfolio} balance={balance} />
            <HoldingsTable holdings={portfolio} />
            <SectorAllocation holdings={portfolio} />
          </>
        );

      case 'watchlist':
        return (
          <>
            <Watchlist onSelectStock={(s) => { setSymbol(s); setActiveTab('trading'); }} />
          </>
        );

      case 'recharge':
        return (
          <div style={{
            background: '#141b2b',
            padding: '30px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c',
            maxWidth: '500px'
          }}>
            <h3 style={{ marginBottom: '20px', color: '#e0e6ed' }}>💳 Recharge Demo Account</h3>
            <p style={{ color: '#8a9bb5', marginBottom: '20px' }}>
              Get more demo credits to trade with!
            </p>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
              {[
                { amount: 500, credits: '₹50,000' },
                { amount: 1000, credits: '₹1,10,000' },
                { amount: 5000, credits: '₹6,00,000' }
              ].map((plan) => (
                <button
                  key={plan.amount}
                  onClick={async () => {
                    try {
                      const response = await fetch(`${API_URL}/recharge`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'include',
                        body: JSON.stringify({ amount: plan.amount })
                      });
                      const data = await response.json();
                      setMessage(data.message || data.error);
                      if (data.balance !== undefined) {
                        setBalance(data.balance);
                        fetchPortfolio();
                      }
                    } catch (error) {
                      setMessage('Error recharging');
                    }
                  }}
                  style={{
                    padding: '20px',
                    background: '#1a2332',
                    border: '1px solid #2a3a5c',
                    borderRadius: '8px',
                    color: 'white',
                    cursor: 'pointer',
                    textAlign: 'center'
                  }}
                >
                  <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#4CAF50' }}>
                    ₹{plan.amount}
                  </div>
                  <div style={{ fontSize: '14px', color: '#8a9bb5', marginTop: '5px' }}>
                    Get {plan.credits}
                  </div>
                </button>
              ))}
            </div>
          </div>
        );

      default:
        return <div>Unknown tab</div>;
    }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#0a0e17' }}>
      <Navbar
        username={username}
        balance={balance}
        onLogout={logout}
      />

      <div style={{ display: 'flex' }}>
        <Sidebar
          activeTab={activeTab}
          onTabChange={setActiveTab}
        />

        <div style={{ flex: 1, padding: '24px' }}>
          {message && (
            <div style={{
              padding: '10px',
              marginBottom: '20px',
              borderRadius: '6px',
              background: '#1a2332',
              textAlign: 'center',
              color: '#e0e6ed'
            }}>
              {message}
            </div>
          )}
          {renderContent()}
        </div>
      </div>
    </div>
  );
}

export default App;
